package jp.personal.hanshinedge.prospective;
import android.content.Context;import android.os.*;import android.webkit.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.*;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;
/** Read-only official transport. No page script is executed: HTML is parsed in an inert DOM. */
public final class JraSource {
 public static final class Page {public final String html;public final JSONObject receipt;Page(String h,JSONObject r){html=h;receipt=r;}}
 public static Page fetch(String path,String cname)throws Exception{if(!path.equals("D")&&!path.equals("S"))throw new IllegalArgumentException("SOURCE_PATH");if(!cname.matches("pw01[A-Za-z0-9]+/[A-Za-z0-9]{2}"))throw new IllegalArgumentException("SOURCE_CNAME");String uri="https://www.jra.go.jp/JRADB/access"+path+".html";HttpURLConnection c=(HttpURLConnection)new URL(uri).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("User-Agent","Mozilla/5.0 JRA-EDGE-READONLY/1.0");c.setRequestProperty("Referer","https://www.jra.go.jp/");c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.setRequestProperty("Cache-Control","no-cache");try{try(OutputStream o=c.getOutputStream()){o.write(("CNAME="+URLEncoder.encode(cname,"UTF-8")).getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw new IOException("HTTP_"+c.getResponseCode());byte[] raw;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>4*1024*1024)throw new IOException("SOURCE_TOO_LARGE");out.write(b,0,n);}raw=out.toByteArray();}long received=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime(),server=c.getDate();Matcher m=Pattern.compile("<meta[^>]+charset\\s*=\\s*[\"']?([A-Za-z0-9_-]+)",Pattern.CASE_INSENSITIVE).matcher(new String(raw,StandardCharsets.ISO_8859_1));String charset=m.find()?m.group(1):"windows-31j";if(charset.equalsIgnoreCase("shift_jis")||charset.equalsIgnoreCase("sjis"))charset="windows-31j";String html=Charset.forName(charset).newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(raw)).toString();StringBuilder hash=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(raw))hash.append(String.format(Locale.ROOT,"%02x",x&255));return new Page(html,new JSONObject().put("source","JRA_OFFICIAL_WEB").put("source_record_id",cname).put("source_uri",uri).put("raw_sha256",hash.toString()).put("source_retrieved_at",Instant.ofEpochMilli(received).toString()).put("received_at_ms",received).put("received_elapsed_ms",elapsed).put("server_time_ms",server).put("http_status",200));}finally{c.disconnect();}}
 public static JSONObject parse(Context c,String asset,String html,JSONObject identity)throws Exception{if(Looper.myLooper()==Looper.getMainLooper())throw new IllegalStateException("PARSER_OFF_MAIN_REQUIRED");String script;try(InputStream in=c.getAssets().open(asset);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);script=out.toString("UTF-8");}CompletableFuture<JSONObject> f=new CompletableFuture<>();Handler main=new Handler(Looper.getMainLooper());final WebView[] view={null};String js=script+"("+JSONObject.quote(html)+","+(identity==null?"null":identity.toString())+")";main.post(()->{try{WebView w=new WebView(c);view[0]=w;w.getSettings().setJavaScriptEnabled(true);w.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){v.evaluateJavascript(js,value->{try{JSONObject p=new JSONObject(value);if(p.has("error"))f.completeExceptionally(new IllegalStateException(p.getString("error")));else f.complete(p);}catch(Exception e){f.completeExceptionally(e);}});}});w.loadData("<!doctype html><title>Inert source parser</title>","text/html","UTF-8");}catch(Exception e){f.completeExceptionally(e);}});try{return f.get(30,TimeUnit.SECONDS);}finally{main.post(()->{if(view[0]!=null)view[0].destroy();});}}
 public static JSONArray today(Context c)throws Exception{Page menu=fetch("D","pw01dli00/F3");JSONArray meetings=parse(c,"catalog_parser.js",menu.html,null).getJSONArray("meetings"),out=new JSONArray();String date=LocalDate.now(ZoneId.of("Asia/Tokyo")).toString();String[] venues={"札幌","函館","福島","新潟","東京","中山","中京","京都","阪神","小倉"};for(int i=0;i<meetings.length();i++){JSONObject m=meetings.getJSONObject(i);if(!date.equals(m.getString("date")))continue;int v=Integer.parseInt(m.getString("venue_code"));if(v<1||v>10)throw new IllegalArgumentException("VENUE_INVALID");m.put("venue",venues[v-1]);Page page=fetch("D",m.getString("cname"));String fields=m.getString("venue_code")+date.substring(0,4)+String.format(Locale.ROOT,"%02d%02d",m.getInt("meeting"),m.getInt("day"))+date.replace("-","");String cname=observed(page.html,"pw01des(?:01|10)"+fields+"/[A-Za-z0-9]{2}");Page card=fetch("D",cname);JSONArray races=parse(c,"catalog_parser.js",card.html,m).getJSONArray("races");for(int j=0;j<races.length();j++)out.put(new JSONObject().put("race",races.getJSONObject(j)).put("receipt",card.receipt));}return out;}
 public static JSONObject latest(Context c,JSONObject registration,JSONObject[] proof)throws Exception{JSONObject r=registration.getJSONObject("race");Page p=fetch("D",registration.getString("source_record_id"));JSONArray a=parse(c,"catalog_parser.js",p.html,r).getJSONArray("races");for(int i=0;i<a.length();i++)if(ProspectiveRuntime.canonical(a.getJSONObject(i)).equals(registration.getString("race_id"))){proof[0]=p.receipt;return a.getJSONObject(i);}throw new IllegalStateException("RACE_NOT_IN_CATALOG");}
 private static String observed(String html,String pattern)throws Exception{Matcher m=Pattern.compile(pattern).matcher(html);if(!m.find())throw new IllegalStateException("OFFICIAL_RESULT_LINK_NOT_OBSERVED");return m.group();}
 public static JSONObject outcome(Context c,JSONObject registration,JSONObject[] proof)throws Exception{JSONObject r=registration.getJSONObject("race");String fields=r.getString("venue_code")+r.getString("date").substring(0,4)+String.format(Locale.ROOT,"%02d%02d",r.getInt("meeting"),r.getInt("day"));String date=r.getString("date").replace("-","");Page menu=fetch("S","pw01sli00/AF");String meeting=observed(menu.html,"pw01srl(?:01|10)"+fields+date+"/[A-Za-z0-9]{2}");Page list=fetch("S",meeting);String token=observed(list.html,"pw01sde(?:01|10)"+fields+String.format(Locale.ROOT,"%02d",r.getInt("race_no"))+date+"/[A-Za-z0-9]{2}");Page result=fetch("S",token);JSONObject value=parse(c,"result_parser.js",result.html,r);proof[0]=result.receipt;return value;}
}
